import type { Findings } from "@/lib/site/findings";

const mm = (v: number) => `${Math.round(v).toLocaleString("en-US")} mm`;
const n2 = (v: number | null) => (v === null ? "unknown" : v.toFixed(2));

/** Real numbers from the committed saved responses. All sentences are generated by the app's own wording functions. */
export default function FindingsView({ f }: { f: Findings }) {
  return (
    <div className="st-find">
      <section id="finding-rain" aria-labelledby="fr-h" className="st-find">
        <h3 id="fr-h">Rain: NASA POWER (about 50 km grid) beside Daymet (1 km grid) and one volunteer gauge</h3>
        <p className="st-note st-note--plain">{f.groundLabel}</p>
        <div className="st-scroll">
          <table className="st-table">
            <caption className="sr-only">Typical yearly rain in two gridded products at each demo place</caption>
            <thead>
              <tr><th scope="col">Place</th><th scope="col">POWER, typical year</th><th scope="col">Daymet, typical year</th><th scope="col">POWER minus Daymet</th><th scope="col">Years agree (R-squared)</th></tr>
            </thead>
            <tbody>
              {f.rain.map((r) => (
                <tr key={r.pinId}>
                  <th scope="row">{r.name}</th>
                  {r.annual ? (
                    <>
                      <td>{mm(r.annual.powerMm)}</td>
                      <td>{mm(r.annual.daymetMm)}</td>
                      <td>{mm(r.annual.diffMm)} a year (ratio {n2(r.annual.ratio)})</td>
                      <td>{n2(r.annual.r2)} over {r.annual.years} years</td>
                    </>
                  ) : (
                    <td colSpan={4}>Nothing to compare: {r.message}</td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        {f.rain.map((r) => (
          <article key={r.pinId} className="st-find__pin">
            <h4>{r.name}</h4>
            {r.labels.length > 0 && <p className="st-find__origin">{r.labels.join(" ")}</p>}
            {r.status === "ok" ? (
              <>
                <ul>
                  {r.daymetLines.slice(0, 2).map((l) => <li key={l}>{l}</li>)}
                  {r.gaugeLines.map((l) => <li key={l}>{l}</li>)}
                </ul>
                {r.caveats.length > 0 && <p className="st-find__origin">{r.caveats[r.caveats.length - 1]}</p>}
              </>
            ) : (
              <p>{r.message}</p>
            )}
          </article>
        ))}
      </section>

      <section id="finding-greenness" aria-labelledby="fg-h" className="st-find">
        <h3 id="fg-h">What the satellite and the land records say about the same pin</h3>
        <p className="st-note st-note--plain">{f.ndviCaveat}</p>
        <div className="st-scroll">
          <table className="st-table">
            <caption className="sr-only">Greenness, land cover and crop history at each demo pin</caption>
            <thead>
              <tr><th scope="col">Place</th><th scope="col">Typical yearly peak greenness (NDVI)</th><th scope="col">Land cover (NLCD, 30 m)</th><th scope="col">Crop history (CDL)</th></tr>
            </thead>
            <tbody>
              {f.greenness.map((g, i) => (
                <tr key={g.pinId}>
                  <th scope="row">{g.name}</th>
                  <td>{g.status === "ok" ? <>{g.peakLine}<small>{g.originLine}</small></> : g.message}</td>
                  <td>{f.land[i].nlcdLine ?? f.land[i].message ?? "Not available."}<small>{f.land[i].nlcdLabel}</small></td>
                  <td>{f.land[i].cdlLine ?? f.land[i].message ?? "Not available."}<small>{f.land[i].cdlLabel}</small></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    </div>
  );
}
